param([Parameter(Mandatory=$true)][string]$RepoRoot,[Parameter(Mandatory=$true)][string]$StateRoot,[ValidateSet("enqueue","list","run")][string]$Action="list",[string]$SourceRoot="",[string]$WorkspaceManifestPath="",[string]$JobId="",[ValidateSet("manual","on_connect","daily")][string]$Schedule="manual",[int]$MaxFiles=1000,[Int64]$MaxBytes=1073741824,[switch]$Execute)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop"
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path;. (Join-Path $PSScriptRoot "_lib_ld_receipts_v1.ps1");. (Join-Path $PSScriptRoot "_lib_ld_destination_profile_v1.ps1");. (Join-Path $PSScriptRoot "_lib_ld_backend_state_v1.ps1");$StateRoot=LDBS-FullPath $StateRoot;$layout=LDBS-Layout $StateRoot;$rows=@();$blockers=@();$writes=$false;$status="listed";$childReceiptPath="";$childReceiptSha=""
if($Action-eq"enqueue"){
 try{if(-not(Test-Path -LiteralPath $SourceRoot -PathType Container)){throw "SOURCE_ROOT_MISSING"};$source=(Resolve-Path -LiteralPath $SourceRoot).Path;$w=LDBS-Workspace $WorkspaceManifestPath $RepoRoot;if(([string]$w.value.backup_mode)-ne"file_backup"){throw "JOB_RUNNER_REQUIRES_FILE_BACKUP_WORKSPACE"};if((LDBS-IsSameOrNested $source ([string]$w.value.workspace_root))-or(LDBS-IsSameOrNested ([string]$w.value.workspace_root) $source)){throw "SOURCE_WORKSPACE_OVERLAP"};$identity=($source.ToLowerInvariant()+"`n"+$w.sha256+"`n"+$Schedule+"`n"+$MaxFiles+"`n"+$MaxBytes);$JobId=(LDREC-HexSha256TextLf $identity).Substring(0,24);$specBase=[ordered]@{schema="ld.backup.job_spec.v1";event_type="ld.backup.job_spec.v1";job_id=$JobId;job_type="mounted_file_backup";source_root=$source;workspace_manifest_path=$w.path;workspace_manifest_sha256=$w.sha256;destination_payload_path=[string]$w.value.payload_path;schedule=$Schedule;max_files=$MaxFiles;max_bytes=$MaxBytes;source_writes_allowed=$false;created_utc=[DateTime]::UtcNow.ToString("o")};$path=Join-Path $layout.jobs ($JobId+".json");if($Execute){$layout=LDBS-EnsureLayout $StateRoot;if(Test-Path -LiteralPath $path){$old=LDBS-ReadJson $path;if(([string]$old.workspace_manifest_sha256-cne[string]$w.sha256)-or([string]$old.source_root-cne$source)){throw "JOB_ID_COLLISION"};$status="already_enqueued"}else{$writes=LDBS-WriteImmutableJson $path $specBase;$status="enqueued"}}else{$status="dry_run_ready"};$rows+=,[ordered]@{job_id=$JobId;job_type="mounted_file_backup";source_root=$source;destination_payload_path=[string]$w.value.payload_path;schedule=$Schedule;job_path=$path;latest_run_status="not_run"}}catch{$blockers+=,[string]$_.Exception.Message;$status="blocked"}
}elseif($Action-eq"run"){
 try{if([string]::IsNullOrWhiteSpace($JobId)){throw "JOB_ID_REQUIRED"};$jobPath=Join-Path $layout.jobs ($JobId+".json");$job=LDBS-ReadJson $jobPath;LDBS-AssertSchema $job "ld.backup.job_spec.v1" $RepoRoot;$w=LDBS-Workspace ([string]$job.workspace_manifest_path) $RepoRoot;if([string]$w.sha256-cne[string]$job.workspace_manifest_sha256){throw "WORKSPACE_MANIFEST_HASH_MISMATCH"};$expectedJobId=(LDREC-HexSha256TextLf (([string]$job.source_root).ToLowerInvariant()+"`n"+[string]$job.workspace_manifest_sha256+"`n"+[string]$job.schedule+"`n"+[string]$job.max_files+"`n"+[string]$job.max_bytes)).Substring(0,24);if($expectedJobId-cne$JobId-or[string]$job.job_id-cne$JobId){throw "JOB_SPEC_IDENTITY_MISMATCH"};if([string]$job.destination_payload_path-cne[string]$w.value.payload_path){throw "JOB_DESTINATION_MISMATCH"};if(-not$Execute){$status="dry_run_ready"}else{$backup=Join-Path $RepoRoot "scripts\media\ld_mounted_media_backup_v1.ps1";$out=& powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $backup -RepoRoot $RepoRoot -SourceRoot ([string]$job.source_root) -DestinationRoot ([string]$job.destination_payload_path) -MaxFiles ([string]$job.max_files) -MaxBytes ([string]$job.max_bytes) -Execute;if($LASTEXITCODE-ne0){throw("BACKUP_EXECUTOR_EXIT_NONZERO:"+$LASTEXITCODE)};$child=LDREC-ReadReceiptFromOutput $out "ld.media.mounted_backup.receipt.v1" (Join-Path $RepoRoot "schemas");if(-not[bool]$child.ok){throw("BACKUP_EXECUTOR_BLOCKED:"+[string]$child.execution_status)};$run=[ordered]@{schema="ld.backup.job_run.v1";event_type="ld.backup.job_run.v1";job_id=$JobId;job_spec_sha256=(LDREC-HexSha256File $jobPath);child_receipt=(LDBS-Plain $child);run_status="succeeded";created_utc=[DateTime]::UtcNow.ToString("o")};$runDir=Join-Path $layout.runs $JobId;LDREC-EnsureDir $runDir;$childReceiptPath=Join-Path $runDir ([DateTime]::UtcNow.ToString("yyyyMMdd_HHmmss_fff")+".json");$writes=LDBS-WriteImmutableJson $childReceiptPath $run;$childReceiptSha=LDREC-HexSha256File $childReceiptPath;$status="succeeded"};$rows+=,[ordered]@{job_id=$JobId;job_type=[string]$job.job_type;source_root=[string]$job.source_root;destination_payload_path=[string]$job.destination_payload_path;schedule=[string]$job.schedule;job_path=$jobPath;latest_run_status=$status}}catch{$blockers+=,[string]$_.Exception.Message;$status="blocked"}
}else{if(Test-Path -LiteralPath $layout.jobs -PathType Container){foreach($f in @(Get-ChildItem -LiteralPath $layout.jobs -File -Filter *.json|Sort-Object Name)){$j=LDBS-ReadJson $f.FullName;LDBS-AssertSchema $j "ld.backup.job_spec.v1" $RepoRoot;$runs=Join-Path $layout.runs ([string]$j.job_id);$latest="not_run";if(Test-Path -LiteralPath $runs){$last=Get-ChildItem -LiteralPath $runs -File -Filter *.json|Sort-Object Name|Select-Object -Last 1;if($null-ne$last){$latest=[string](LDBS-ReadJson $last.FullName).run_status}};$rows+=,[ordered]@{job_id=[string]$j.job_id;job_type=[string]$j.job_type;source_root=[string]$j.source_root;destination_payload_path=[string]$j.destination_payload_path;schedule=[string]$j.schedule;job_path=$f.FullName;latest_run_status=$latest}}}}
$ok=($blockers.Count-eq0);$receipt=[ordered]@{schema="ld.backup.job.receipt.v1";event_type="ld.backup.job.receipt.v1";ok=[bool]$ok;availability=$(if($ok){"available"}else{"blocked"});repo_root=$RepoRoot;state_root=$StateRoot;action=$Action;execute_requested=[bool]$Execute;writes_state=[bool]$writes;job_count=[int]$rows.Count;execution_status=$status;child_receipt_path=$childReceiptPath;child_receipt_sha256=$childReceiptSha;rows=@($rows);blockers=@($blockers);created_utc=[DateTime]::UtcNow.ToString("o")};$json=$receipt|ConvertTo-Json -Depth 100 -Compress;Write-Output $json;if($ok){Write-Output "LD_BACKUP_JOB_OK"}else{Write-Output "LD_BACKUP_JOB_BLOCKED"}
